@Observable
final class SearchViewModel {
    var results: [Item] = []

    func search(_ query: String) {
        Task {
            let url = makeURL(query)
            let (data, _) = try await URLSession.shared.data(from: url)
            results = try JSONDecoder().decode([Item].self, from: data)
        }
    }
}

func exportAllPages() async throws -> [Record] {
    var all: [Record] = []
    var page = 1
    while true {
        let batch = try await fetchPage(page)
        if batch.isEmpty { break }
        all += batch
        page += 1
    }
    return all
}

