func fetchFeed(authToken: String) async throws -> [Post] {
    var request = URLRequest(url: feedURL)
    request.setValue("Bearer \(authToken)", forHTTPHeaderField: "Authorization")
    let (data, _) = try await URLSession.shared.data(for: request)
    return try JSONDecoder().decode([Post].self, from: data)
}

func send(_ request: URLRequest) async throws -> Data {
    let (data, response) = try await URLSession.shared.data(for: request)
    let status = (response as? HTTPURLResponse)?.statusCode ?? 200
    if status == 401 {
        return try await send(request)
    }
    return data
}

func authorizedFetch(_ request: URLRequest) async throws -> Data {
    let (data, response) = try await send(request, token: currentToken)
    if (response as? HTTPURLResponse)?.statusCode == 401 {
        currentToken = try await refreshToken()
        return try await send(request, token: currentToken).0
    }
    return data
}
